import { Component, computed, input, output } from '@angular/core';
import { LoadingStateComponent } from '../loading-state/loading-state.component';

export type TableStateType = 'loading' | 'empty' | 'no-results' | 'error';

interface TableStateConfig {
  icon: string;
  title: string;
  description: string;
}

@Component({
  selector: 'tpp-table-state',
  imports: [LoadingStateComponent],
  templateUrl: './table-state.component.html',
  styleUrl: './table-state.component.css',
})
export class TableStateComponent {
  type = input<TableStateType>('empty');
  title = input<string>('');
  description = input<string>('');
  retry = output<void>();

  isLoading = computed(() => this.type() === 'loading');
  showRetry = computed(() => this.type() === 'error');
  config = computed(() => this.getConfig(this.type()));

  displayedTitle = computed(() => this.title() || this.config().title);
  displayedDescription = computed(() => this.description() || this.config().description);

  getConfig(type: TableStateType): TableStateConfig {
    return this.stateConfig[type] ?? this.stateConfig['empty'];
  }

  private readonly stateConfig: Record<TableStateType, TableStateConfig> = {
    loading: {
      icon: '',
      title: 'Cargando datos',
      description: 'Por favor, espere un momento...',
    },
    empty: {
      icon: 'ti-inbox',
      title: 'No hay registros',
      description: 'Crea un nuevo registro para comenzar.',
    },
    'no-results': {
      icon: 'ti-search',
      title: 'No se encontraron resultados',
      description: 'Intente ajustar los filtros de búsqueda.',
    },
    error: {
      icon: 'ti-alert-triangle',
      title: 'Error al cargar los datos',
      description: 'No se pudieron cargar los registros. Inténtelo nuevamente.',
    },
  };
}